import 'package:flutter/material.dart'; import 'calculators/calculator_screen.dart';
class CalculatorMenuScreen extends StatelessWidget { const CalculatorMenuScreen({super.key}); final items=const [('Income Tax Calculator',Icons.receipt_long,'tax'),('In-Hand Salary Calculator',Icons.payments,'salary'),('HRA Exemption Calculator',Icons.home_work,'hra'),('Gratuity Calculator',Icons.card_giftcard,'gratuity'),('EPF Maturity Calculator',Icons.savings,'epf')]; @override Widget build(BuildContext c)=>GridView.builder(padding:const EdgeInsets.all(16),gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:2,crossAxisSpacing:12,mainAxisSpacing:12),itemCount:items.length,itemBuilder:(_,i){final x=items[i];return Card(child:InkWell(onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>CalculatorScreen(type:x.$3,title:x.$1))),child:Padding(padding:const EdgeInsets.all(16),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(x.$2,size:40,color:Theme.of(c).colorScheme.primary),const SizedBox(height:12),Text(x.$1,textAlign:TextAlign.center,style:const TextStyle(fontWeight:FontWeight.bold))]))));});}
}
